def is_user_staff(member: discord.Member, guild: discord.Guild, staff_role_id):
    if member.guild_permissions.administrator or member.guild_permissions.manage_channels:
        return True
    if staff_role_id:
        try:
            role = guild.get_role(int(staff_role_id))
            if role and role in member.roles:
                return True
        except:
            pass
    for r in member.roles:
        r_name = r.name.lower()
        if any(kw in r_name for kw in ["admin", "staff", "owner", "support", "إدارة", "مسؤول", "دعم", "صاحب"]):
            return True
    return False

def get_target_category(guild, cat_id_key, search_keywords):
    cfg = load_config()
    configured_id = cfg.get(cat_id_key)
    if configured_id:
        try:
            cat = guild.get_channel(int(configured_id))
            if cat and isinstance(cat, discord.CategoryChannel):
                return cat
        except:
            pass
    for cat in guild.categories:
        cat_lower = cat.name.lower()
        if any(kw.lower() in cat_lower for kw in search_keywords):
            return cat
    return None

class CloseTicketView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="إغلاق التذكرة", style=discord.ButtonStyle.danger, emoji="🔒", custom_id="fet_btn_close_ticket")
    async def close_ticket_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        channel = interaction.channel
        guild = interaction.guild
        cfg = load_config()
        staff_role_id = cfg.get("staff_role_id", "")
        
        is_owner = False
        owner_id = None
        if channel.topic:
            m = re.search(r'(?:FET_TICKET_OWNER:|ID:\s*)(\d+)', channel.topic)
            if m:
                try:
                    owner_id = int(m.group(1))
                    is_owner = (interaction.user.id == owner_id)
                except:
                    pass
                
        is_staff = is_user_staff(interaction.user, guild, staff_role_id)
        if not (is_owner or is_staff):
            await interaction.response.send_message("❌ عذراً، فقط صاحب التذكرة أو طاقم الإدارة يمكنهم إغلاق التذكرة.", ephemeral=True)
            return

        await interaction.response.defer()
        
        # 1. سحب صلاحية الرؤية بالكامل من العميل ومن أي عضو غير إداري
        if owner_id:
            owner_member = guild.get_member(owner_id)
            if not owner_member:
                try:
                    owner_member = await guild.fetch_member(owner_id)
                except:
                    pass
            if owner_member:
                try:
                    await channel.set_permissions(owner_member, view_channel=False, send_messages=False, read_message_history=False)
                except Exception as e:
                    logger.warning(f"Could not hide channel from owner: {e}")

        for target, _ in list(channel.overwrites.items()):
            if isinstance(target, discord.Member) and not is_user_staff(target, guild, staff_role_id) and target.id != guild.me.id:
                try:
                    await channel.set_permissions(target, view_channel=False, send_messages=False, read_message_history=False)
                except Exception as e:
                    logger.warning(f"Could not set permission for member {target}: {e}")

        # 2. نقل التذكرة إلى قسم التكتات المغلقة وتغيير اسمها مع الاحتفاظ بالاسم الأصلي
        target_closed_category = get_target_category(guild, "closed_category_id", ["تكتات مغلقة", "تذاكر مغلقة", "closed tickets", "closed", "مغلق"])
        
        clean_name = channel.name.replace("closed-", "")
        new_name = f"closed-{clean_name}"[:95]
        try:
            if target_closed_category:
                await channel.edit(category=target_closed_category, name=new_name)
            else:
                await channel.edit(name=new_name)
        except Exception as e:
            logger.warning(f"Could not rename/move channel: {e}")

        close_embed = discord.Embed(
            title="🔒 تم إغلاق التذكرة",
            description=f"تم إغلاق التذكرة وسحب صلاحية الرؤية من العميل بنجاح.\nبواسطة: {interaction.user.mention}\n\nيمكن للإدارة فقط إعادة فتح التذكرة أو حذفها نهائياً.",
            color=discord.Color.from_str("#ff4757")
        )
        if os.path.exists(os.path.join(ASSETS_DIR, "logo_circle.png")):
            close_embed.set_footer(text="FET STORE | Ticket Closed", icon_url="attachment://logo_circle.png")
            file = discord.File(os.path.join(ASSETS_DIR, "logo_circle.png"), filename="logo_circle.png")
            await channel.send(embed=close_embed, file=file, view=ClosedTicketActionView())
        else:
            close_embed.set_footer(text="FET STORE | Ticket Closed")
            await channel.send(embed=close_embed, view=ClosedTicketActionView())

class ClosedTicketActionView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="إعادة فتح التذكرة", style=discord.ButtonStyle.success, emoji="🔓", custom_id="fet_btn_reopen_ticket")
    async def reopen_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        channel = interaction.channel
        guild = interaction.guild
        cfg = load_config()
        staff_role_id = cfg.get("staff_role_id", "")
        
        if not is_user_staff(interaction.user, guild, staff_role_id):
            await interaction.response.send_message("❌ عذراً، فقط طاقم الإدارة يمكنهم إعادة فتح التذكرة.", ephemeral=True)
            return

        await interaction.response.defer()

        # إعادة صلاحية الرؤية لصاحب التذكرة
        owner_id = None
        if channel.topic:
            m = re.search(r'(?:FET_TICKET_OWNER:|ID:\s*)(\d+)', channel.topic)
            if m:
                try:
                    owner_id = int(m.group(1))
                except:
                    pass
        if owner_id:
            owner_member = guild.get_member(owner_id)
            if not owner_member:
                try:
                    owner_member = await guild.fetch_member(owner_id)
                except:
                    pass
            if owner_member:
                try:
                    await channel.set_permissions(owner_member, view_channel=True, send_messages=True, attach_files=True, embed_links=True, read_message_history=True)
                except Exception as e:
                    logger.warning(f"Could not restore owner permissions: {e}")

        active_cat = get_target_category(guild, "ticket_category_id", ["تكتات فعالة", "تذاكر فعالة", "active tickets", "tickets", "تذاكر"])
        restored_name = channel.name.replace("closed-", "")[:95]
        try:
            if active_cat:
                await channel.edit(category=active_cat, name=restored_name)
            else:
                await channel.edit(name=restored_name)
        except Exception as e:
            logger.warning(f"Could not rename/move channel on reopen: {e}")

        reopen_embed = discord.Embed(
            title="🔓 تمت إعادة فتح التذكرة",
            description=f"قام {interaction.user.mention} بإعادة فتح التذكرة واستعادة صلاحية العميل.",
            color=discord.Color.from_str("#00ff41")
        )
        await channel.send(embed=reopen_embed, view=CloseTicketView())

    @discord.ui.button(label="حذف التذكرة نهائياً", style=discord.ButtonStyle.danger, emoji="🗑️", custom_id="fet_btn_delete_ticket")
    async def delete_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        channel = interaction.channel
        guild = interaction.guild
        cfg = load_config()
        staff_role_id = cfg.get("staff_role_id", "")
        
        if not is_user_staff(interaction.user, guild, staff_role_id):
            await interaction.response.send_message("❌ عذراً، فقط طاقم الإدارة يمكنهم حذف التذكرة.", ephemeral=True)
            return

        await interaction.response.send_message("⏳ سيتم حذف التذكرة نهائياً خلال 3 ثوانٍ...")
        await asyncio.sleep(3)
        try:
            await channel.delete(reason=f"Ticket deleted by {interaction.user}")
        except Exception as e:
            logger.error(f"Error deleting channel: {e}")

# [[ Review / Feedback System ]] #
class ReviewModal(discord.ui.Modal, title="⭐ تقييم تجربة العميل - FET STORE"):
    feedback = discord.ui.TextInput(
        label="كيف تشوف تعاملنا معك؟",
        style=discord.TextStyle.paragraph,
        placeholder="اكتب رأيك بصراحة عن جودة الخدمة، سرعة الرد، والتعامل...",
        required=True,
        max_length=1000
    )
    rating = discord.ui.TextInput(
        label="كم تقيمنا من 10؟",
        style=discord.TextStyle.short,
        placeholder="مثال: 10 أو 10/10 أو 9",
        required=True,
        max_length=20
    )

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        guild = interaction.guild
        user = interaction.user
        feedback_val = self.feedback.value.strip()
        rating_val = self.rating.value.strip()

        cfg = load_config()
        reviews_channel_id = cfg.get("reviews_channel_id")
        target_channel = None
        if reviews_channel_id:
            try:
                target_channel = guild.get_channel(int(reviews_channel_id))
            except:
                pass

        if not target_channel:
            for ch in guild.text_channels:
                ch_name_lower = ch.name.lower()
                if any(kw in ch_name_lower for kw in ["تقييمك", "تقييم", "تقيم", "reviews", "feedback"]):
                    target_channel = ch
                    break

        rating_clean = rating_val.replace("/10", "").strip()
        rating_display = f"{rating_clean} / 10" if "/10" not in rating_val else rating_val

        embed = discord.Embed(
            title="⭐ تقييم عميل جديد | FET STORE",
            description=(
                f"سعدنا بالعميل الجديد : {user.mention}\n\n"
                f"💬 **تقييم العميل :**\n{feedback_val}\n\n"
                f"⭐ **التقييم من 10 :**\n**{rating_display}**"
            ),
            color=discord.Color.from_str("#00ff41")
        )

        files = []
        logo_path = os.path.join(ASSETS_DIR, "logo_circle.png")
        if not os.path.exists(logo_path):
            logo_path = os.path.join(ASSETS_DIR, "logo.png")
        if os.path.exists(logo_path):
            files.append(discord.File(logo_path, filename="logo_circle.png"))
            embed.set_thumbnail(url="attachment://logo_circle.png")
            embed.set_footer(text="FET STORE | شكراً لثقتكم بنا", icon_url="attachment://logo_circle.png")
        else:
            embed.set_footer(text="FET STORE | شكراً لثقتكم بنا")

        banner_path = os.path.join(ASSETS_DIR, "review_banner.png")
        if os.path.exists(banner_path):
            files.append(discord.File(banner_path, filename="review_banner.png"))
            embed.set_image(url="attachment://review_banner.png")

        dest = target_channel if target_channel else interaction.channel
        try:
            if files:
                await dest.send(content=f"📢 تقييم جديد من العميل : {user.mention}", embed=embed, files=files)
            else:
                await dest.send(content=f"📢 تقييم جديد من العميل : {user.mention}", embed=embed)
        except Exception as e:
            logger.error(f"Error sending review to channel: {e}")

        await interaction.followup.send("✅ شكراً جزيلاً لك على تقييمك الرائع! نسعد ونتشرف دائماً بخدمتك 💚", ephemeral=True)
        try:
            dest_mention = target_channel.mention if target_channel else ""
            await interaction.channel.send(f"💐 شكراً لك {user.mention} على تقييمك الجميل لمتجر **FET STORE**! {dest_mention}")
        except:
            pass

