@app.route("/")
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route("/static/img/<path:filename>")
def serve_static_img(filename):
    p = os.path.join(ASSETS_DIR, filename)
    if os.path.exists(p):
        return send_file(p)
    return "", 404

@app.route("/api/status")
def api_status():
    cfg = load_config()
    is_online = (bot is not None) and bot.is_ready()
    guilds_data = []
    
    if is_online:
        for g in bot.guilds:
            channels = [{"id": str(c.id), "name": c.name, "type": str(c.type)} for c in g.text_channels]
            roles = [{"id": str(r.id), "name": r.name} for r in g.roles if r.name != "@everyone"]
            categories = [{"id": str(cat.id), "name": cat.name} for cat in g.categories]
            guilds_data.append({
                "id": str(g.id),
                "name": g.name,
                "icon": str(g.icon.url) if g.icon else None,
                "channels": channels,
                "roles": roles,
                "categories": categories
            })
            
    return jsonify({
        "online": is_online,
        "bot_user": str(bot.user) if is_online else None,
        "bot_avatar": str(bot.user.avatar.url) if is_online and bot.user.avatar else None,
        "bot_error": bot_error_msg,
        "config": cfg,
        "guilds": guilds_data
    })

@app.route("/api/config/save", methods=["POST"])
def api_config_save():
    data = request.json or {}
    cfg = load_config()
    old_token = cfg.get("token", "").strip()
    new_token = data.get("token", "").strip()
    
    cfg.update(data)
    save_config(cfg)
    
    is_ready = (bot is not None) and bot.is_ready()
    if new_token and (new_token != old_token or not is_ready):
        start_bot_in_background(new_token)
        
    return jsonify({"status": "ok", "message": "تم حفظ الإعدادات بنجاح!"})

@app.route("/api/ticket/send", methods=["POST"])
def api_ticket_send():
    if bot is None or not bot.is_ready():
        return jsonify({"status": "error", "message": "البوت غير متصل بالديسكورد! يرجى التأكد من التوكن."}), 400
        
    data = request.json or {}
    channel_id = int(data.get("channel_id")) if data.get("channel_id") else None
    if not channel_id:
        return jsonify({"status": "error", "message": "يرجى اختيار الروم."}), 400

    channel = bot.get_channel(channel_id)
    if not channel:
        return jsonify({"status": "error", "message": "الروم غير موجودة أو لا يمتلك البوت صلاحية الوصول لها."}), 404

    title = data.get("title", "نظام التذاكر - FET STORE")
    desc = data.get("description", "")
    placeholder = data.get("placeholder", "اختر نوع الخدمة المطلوبة - 📁")
    color_hex = data.get("color", "#00ff41")
    departments = data.get("departments", DEFAULT_DEPARTMENTS)

    # Save departments to config
    cfg = load_config()
    cfg["departments"] = departments
    save_config(cfg)

    async def send_panel():
        embed = discord.Embed(
            title=title,
            description=desc,
            color=discord.Color.from_str(color_hex)
        )
        
        files = []
        logo_path = os.path.join(ASSETS_DIR, "logo_circle.png")
        if not os.path.exists(logo_path):
            logo_path = os.path.join(ASSETS_DIR, "logo.png")
            
        banner_path = os.path.join(ASSETS_DIR, "ticket_banner.png")
        
        if os.path.exists(logo_path):
            files.append(discord.File(logo_path, filename="logo_circle.png"))
            embed.set_thumbnail(url="attachment://logo_circle.png")
            embed.set_author(name="FET STORE - Official Ticket System", icon_url="attachment://logo_circle.png")
            embed.set_footer(text="FET STORE | Best Quality Products", icon_url="attachment://logo_circle.png")
        else:
            embed.set_author(name="FET STORE - Official Ticket System")
            embed.set_footer(text="FET STORE | Best Quality Products")

        if os.path.exists(banner_path):
            files.append(discord.File(banner_path, filename="ticket_banner.png"))
            embed.set_image(url="attachment://ticket_banner.png")

        view = TicketPanelView(placeholder=placeholder, departments=departments)
        bot.add_view(view)
        if files:
            await channel.send(embed=embed, files=files, view=view)
        else:
            await channel.send(embed=embed, view=view)

    future = asyncio.run_coroutine_threadsafe(send_panel(), bot.loop)
    try:
        future.result(timeout=10)
        return jsonify({"status": "ok", "message": "تم إرسال لوحة التذاكر إلى الديسكورد بنجاح!"})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500

